// Bucle de control de actitud simplificado (un eje)
float targetAngle = 0.0;
float Kp = 2.5, Kd = 0.8;
float prevError = 0;

void loop() {
  float angle = readImuAngle();       // grados, filtrado
  float error = targetAngle - angle;
  float derivative = (error - prevError) / dt;
  float torqueDemand = Kp * error + Kd * derivative;
  prevError = error;

  // Traduce demanda de par a ancho de pulso de valvula (saturado)
  int pulseMs = constrain(abs(torqueDemand) * 4, 0, 40);
  if (pulseMs > 3) {
    if (torqueDemand > 0) fireValve(VALVE_CW, pulseMs);
    else fireValve(VALVE_CCW, pulseMs);
  }
  delay(20); // ciclo de control ~50Hz
}

#include <Wire.h>
#define AS5600_ADDR 0x36
#define STEPS_PER_REV 3200L  // 200 pasos * 16 micropasos

long currentStep = 0;

uint16_t readEncoderRaw() {
  Wire.beginTransmission(AS5600_ADDR);
  Wire.write(0x0C); // registro ANGLE
  Wire.endTransmission(false);
  Wire.requestFrom(AS5600_ADDR, 2);
  uint16_t hi = Wire.read();
  uint16_t lo = Wire.read();
  return ((hi << 8) | lo) & 0x0FFF;
}

void controlLoop() {
  uint16_t expected = (currentStep % STEPS_PER_REV) * 4096L / STEPS_PER_REV;
  uint16_t actual = readEncoderRaw();
  int error = (int)expected - (int)actual;
  if (error > 2048) error -= 4096;
  if (error < -2048) error += 4096;

  if (abs(error) > 20) { // ~1.75 grados de tolerancia
    // Pasos perdidos detectados: reenviar pasos de correccion
    stepMotor(error > 0 ? 1 : -1);
  }
}
